const listUsersAdmin = `-- name: ListUsersAdmin :many
SELECT u.id, u.state, u.display_name, u.freeze_time, u.freeze_reason, u.freeze_actor_subject, u.freeze_actor_username, u.delete_time, u.purge_time, u.create_time, u.update_time FROM user_account u
WHERE ($1::smallint IS NULL OR u.state = $1::smallint)
  AND ($2::bool OR u.state NOT IN (3, 4))
  AND ($3::timestamptz IS NULL OR u.create_time >= $3::timestamptz)
  AND ($4::timestamptz IS NULL OR u.create_time <  $4::timestamptz)
  AND (NOT $5::bool OR EXISTS (
        SELECT 1 FROM identity i
        WHERE i.user_id = u.id AND i.delete_time IS NULL
          AND ($6::smallint IS NULL OR i.kind = $6::smallint)
          AND (cardinality($7::text[]) = 0 OR i.subject_digest = ANY($7::text[]))
          AND ($8::text IS NULL OR i.hint_prefix = $8::text)
          AND ($9::text IS NULL OR i.hint_suffix = $9::text)))
  AND ($10::timestamptz IS NULL
       OR (u.create_time, u.id) > ($10::timestamptz, $11::text))
ORDER BY u.create_time, u.id
LIMIT $12::int
`

type ListUsersAdminParams struct {
	State          *int16
	IncludeDeleted bool
	CreateTimeMin  *time.Time
	CreateTimeMax  *time.Time
	ByIdentity     bool
	IdentityKind   *int16
	Digests        []string
	HintPrefix     *string
	HintSuffix     *string
	AfterTime      *time.Time
	AfterID        *string
	PageLimit      int32
}

// 管理端 GET /users：可空参数实现可选过滤（sqlc.narg），keyset 分页 ORDER BY create_time, id（§3.4），
// 由 user_account_create_time_id_idx 提供索引序，避免每页全表排序。
// state NOT IN (3, 4) 写死数值（PENDING_DELETION / DELETED，与 enum 钉死），与 purge 索引谓词同理。
// 身份条件落在同一条活跃身份行（单个 EXISTS）；identity.phone/email 的 digests 是 AllDigests 的结果。
// 注意：EXISTS 子查询里的 ($n IS NULL OR col = $n) 形式在 PostgreSQL 通用计划（generic plan）下可能不走
// identity_kind_* 的部分索引；若观测到这类退化，优先在连接池上设 plan_cache_mode = force_custom_plan，
// 或对本查询 SET LOCAL。
func (q *Queries) ListUsersAdmin(ctx context.Context, arg ListUsersAdminParams) ([]UserAccount, error) {
	rows, err := q.db.Query(ctx, listUsersAdmin,
		arg.State,
		arg.IncludeDeleted,
		arg.CreateTimeMin,
		arg.CreateTimeMax,
		arg.ByIdentity,
		arg.IdentityKind,
		arg.Digests,
		arg.HintPrefix,
		arg.HintSuffix,
		arg.AfterTime,
		arg.AfterID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserAccount
	for rows.Next() {
		var i UserAccount
		if err := rows.Scan(
			&i.ID,
			&i.State,
			&i.DisplayName,
			&i.FreezeTime,
			&i.FreezeReason,
			&i.FreezeActorSubject,
			&i.FreezeActorUsername,
			&i.DeleteTime,
			&i.PurgeTime,
			&i.CreateTime,
			&i.UpdateTime,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

