const purgeUser = `-- name: PurgeUser :execrows
UPDATE user_account
SET state = $1, display_name = NULL, freeze_time = NULL, freeze_reason = NULL,
    freeze_actor_subject = NULL, freeze_actor_username = NULL,
    purge_time = $2::timestamptz, update_time = $2::timestamptz
WHERE id = $3 AND state = $4
`

type PurgeUserParams struct {
	DeletedState enum.UserState
	Now          time.Time
	ID           string
	PendingState enum.UserState
}

// 匿名化账号行：展示名与冻结快照置 NULL，state → DELETED，purge_time 改写为实际执行时刻（delete_time 保留）。
// WHERE 带 state 做二次保险：调用方持锁并已复核状态，这里再钉一次避免把非 PENDING_DELETION 的行写成 DELETED。
func (q *Queries) PurgeUser(ctx context.Context, arg PurgeUserParams) (int64, error) {
	result, err := q.db.Exec(ctx, purgeUser,
		arg.DeletedState,
		arg.Now,
		arg.ID,
		arg.PendingState,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

